func:
// Clear the confirmed-registration set on every (re)deploy so a redeploy
// can't leave stale entries that fool the writer or suppress the
// re-register heartbeat.
global.set('opcua_registered', {});
node.status({ fill: 'grey', shape: 'ring', text: 'registration reset' });
return null;

// Register the demo energy-meter address space (13 Double variables).
// Runs on start, on a periodic heartbeat, and on catch-driven reconcile,
// so registration self-sustains regardless of how the flow was deployed
// or restarted (a one-shot inject can be skipped by a partial deploy).
// Idempotent: only (re)adds variables not already confirmed — re-adding
// an existing NodeId throws 'already registered' in node-opcua. The
// addVariable messages are paced by the downstream no-drop delay so a
// boot burst can't overrun the server.
const METRICS = [
    'active_power_l1_w', 'active_power_l2_w', 'active_power_l3_w',
    'active_power_total_w',
    'voltage_l1_v', 'voltage_l2_v', 'voltage_l3_v',
    'current_l1_a', 'current_l2_a', 'current_l3_a',
    'power_factor', 'total_energy_kwh', 'frequency_hz'
];
const registered = global.get('opcua_registered') || {};
const have = Object.keys(registered).length;
node.status({
    fill: have >= METRICS.length ? 'green' : 'yellow',
    shape: 'dot',
    text: 'registered ' + have + '/' + METRICS.length
});
const missing = METRICS.filter((m) => !registered[m]);
if (missing.length === 0) {
    return null;
}
const msgs = missing.map((m) => ({
    payload: { opcuaCommand: 'addVariable' },
    topic: 'ns=1;s=FACIS.EnergyMeter.' + m + ';datatype=Double;value=0'
}));
node.send([msgs]);
return null;

// Push the latest meter snapshot into the OPC UA server address space.
// Gate on ground truth: only write once all 13 variables are confirmed
// registered ('opcua_registered', filled by the server's addVariable
// confirmations). Avoids 'Variable not found' / 'Server is not running'
// during boot or right after a redeploy. If a redeploy left a stale full
// set, the first write fails 'not found' and the catch reconcile clears
// it, which re-gates the writer until re-registration completes.
const METRICS_TOTAL = 13;
const registered = global.get('opcua_registered') || {};
if (Object.keys(registered).length < METRICS_TOTAL) {
    node.status({ fill: 'grey', shape: 'ring', text: 'waiting registration' });
    return null;
}

const meters = global.get('latest_meters') || [];
if (meters.length === 0) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no meter data yet' });
    return null;
}

const meterIndex = Number(env.get('METER_INDEX') || 0);
const meter = meters[meterIndex] || meters[0];
if (!meter || !meter.readings) {
    return null;
}

const r = meter.readings;
const phases = [r.active_power_l1_w, r.active_power_l2_w, r.active_power_l3_w];
const allPhasesPresent = phases.every((v) => typeof v === 'number' && Number.isFinite(v));
const totalActiveW = allPhasesPresent ? phases.reduce((a, b) => a + b, 0) : undefined;

const values = {
    active_power_l1_w: r.active_power_l1_w,
    active_power_l2_w: r.active_power_l2_w,
    active_power_l3_w: r.active_power_l3_w,
    active_power_total_w: totalActiveW,
    voltage_l1_v: r.voltage_l1_v,
    voltage_l2_v: r.voltage_l2_v,
    voltage_l3_v: r.voltage_l3_v,
    current_l1_a: r.current_l1_a,
    current_l2_a: r.current_l2_a,
    current_l3_a: r.current_l3_a,
    power_factor: r.power_factor,
    total_energy_kwh: r.total_energy_kwh,
    frequency_hz: r.frequency_hz
};

const updates = [];
for (const [name, value] of Object.entries(values)) {
    if (typeof value !== 'number' || !Number.isFinite(value)) continue;
    updates.push({
        messageType: 'Variable',
        namespace: 1,
        variableName: 'FACIS.EnergyMeter.' + name,
        variableValue: value,
        sourceTimestamp: meter.timestamp
    });
}
if (updates.length === 0) {
    return null;
}

global.set('opcua_last_update_count', updates.length);
global.set('opcua_last_update_meter', meter.meter_id);
node.status({ fill: 'green', shape: 'dot', text: 'writing ' + updates.length + ' @ ' + meter.meter_id });

return { payload: updates };

// Ground-truth registration tracker. The OPC UA server emits one
// confirmation per successful addVariable:
//   { payload: { messageType: 'Variable',
//                variableName: '1:FACIS.EnergyMeter.<metric>',
//                nodeId: 'ns=1;s=FACIS.EnergyMeter.<metric>' } }
// Record each confirmed metric so the writer only publishes once the
// address space actually holds the variables. Ignore the server's echo
// of value-update batches (payload is an array) and command echoes.
// Passes the confirmation through so it is observable on a debug node.
const p = msg.payload;
if (!p || Array.isArray(p) || p.messageType !== 'Variable' || !p.nodeId) {
    return null;
}
const marker = 'FACIS.EnergyMeter.';
const vn = String(p.variableName || '');
const idx = vn.indexOf(marker);
if (idx < 0) {
    return null;
}
const metric = vn.slice(idx + marker.length);
if (!metric) {
    return null;
}
const registered = global.get('opcua_registered') || {};
registered[metric] = true;
global.set('opcua_registered', registered);
const have = Object.keys(registered).length;
node.status({
    fill: have >= 13 ? 'green' : 'yellow',
    shape: 'dot',
    text: have + '/13 confirmed'
});
return msg;

// On a server error decide whether the address space lost our variables.
// 'Variable not found' / 'Server is not running' both mean the writes
// hit a server that no longer has the nodes (e.g. after a restart) — drop
// the cached confirmations so the rate-limited re-register adds them all
// back and the writer re-gates until it is done. Other errors just pass
// through to a re-register attempt without clearing.
const err = String((msg && msg.error && msg.error.message) || (msg && msg.error) || '');
if (/not found|not running/i.test(err)) {
    global.set('opcua_registered', {});
    node.status({ fill: 'red', shape: 'ring', text: 'address space lost — re-registering' });
}
return msg;
